import { registerWebComponents } from '@domg-wc/common';
import { VlTitleComponent } from '@domg-wc/components/atom';
import { VlBreadcrumbComponent, VlBreadcrumbItemComponent, VlCascaderComponent } from '@domg-wc/components/block';

// VlCascaderComponent registreert zelf vl-cascader-item, vl-link, vl-icon en vl-text, maar niet vl-breadcrumb en
// vl-breadcrumb-item voor het slot breadcrumb-placeholder.
// Een klik op de inhoud van het slot label opent het volgende niveau; label="West-Vlaanderen" komt in de breadcrumb.
registerWebComponents([VlCascaderComponent, VlBreadcrumbComponent, VlBreadcrumbItemComponent, VlTitleComponent]);
